SELECT a.jst_3196_f5823 AS workFileType, a.jst_3196_f5815 AS workFileId, a.jst_3196_f4960 AS workFileDoneTime, a.jst_3196_f5816 AS workPerson, a.jst_3196_f5182 AS workGroup, a.jst_3196_f5817 AS workFilePjName, a.jst_3196_f5818 AS workFileProject, a.jst_3196_f5819 AS workFileAmountType, a.jst_3196_f4967 AS workFileSingleAmount, a.jst_3196_f5820 AS workFileTotalAmount, a.jst_3196_f5821 AS workFileAmountDesc, a.jst_3196_f5822 AS workDesc, '997' AS formId, a.jst_3196_id AS recordId FROM jst_3196 a
AND a.jst_3196_f4960 BETWEEN #{workFileDoneStartTime} AND #{workFileDoneEndTime}
AND a.jst_3196_f5182 LIKE CONCAT('%', #{workFileProject}, '%')

SELECT ROUND(IFNULL(SUM(a.project_amount),0),2) as amount FROM ( SELECT `jst_3124`.`jst_3124_f5171` AS `project_number`,`jst_3124`.`jst_3124_f5170` AS `project_name`,`jst_3124`.`jst_3124_f3993` AS `project_amount`,`jst_3124`.`jst_3124_id` AS `project_id` FROM `jst_3124` UNION ALL SELECT `jst_3131`.`jst_3131_f5166` AS `jst_3131_f5166`,`jst_3131`.`jst_3131_f4097` AS `jst_3131_f4097`,`jst_3131`.`jst_3131_f4101` AS `jst_3131_f4101`,`jst_3131`.`jst_3131_FOREIGNKEY` AS `jst_3131_FOREIGNKEY` FROM `jst_3131` UNION ALL SELECT `jst_3210`.`jst_3210_f4112` AS `jst_3210_f4112`,`jst_3210`.`jst_3210_f4111` AS `jst_3210_f4111`,`jst_3210`.`jst_3210_f4113` AS `jst_3210_f4113`,`jst_3210`.`jst_3210_id` AS `jst_3210_id` FROM `jst_3210` UNION ALL SELECT `jst_3150`.`jst_3150_f5178` AS `jst_3150_f5178`,`jst_3150`.`jst_3150_f5177` AS `jst_3150_f5177`,`jst_3150`.`jst_3150_f4084` AS `jst_3150_f4084`,`jst_3150`.`jst_3150_id` AS `jst_3150_id` FROM `jst_3150` UNION ALL SELECT `jst_3138`.`jst_3138_f5169` AS `jst_3138_f5169`,`jst_3138`.`jst_3138_f5168` AS `jst_3138_f5168`,`jst_3138`.`jst_3138_f4203` AS `jst_3138_f4203`,`jst_3138`.`jst_3138_id` AS `jst_3138_id` FROM `jst_3138` UNION ALL SELECT `jst_3209`.`jst_3209_f4112` AS `jst_3209_f4112`,`jst_3209`.`jst_3209_f4111` AS `jst_3209_f4111`,`jst_3209`.`jst_3209_f4113` AS `jst_3209_f4113`,`jst_3209`.`jst_3209_id` AS `jst_3209_id` FROM `jst_3209` UNION ALL SELECT `jst_3210`.`jst_3210_f4112` AS `jst_3210_f4112`,`jst_3210`.`jst_3210_f4111` AS `jst_3210_f4111`,`jst_3210`.`jst_3210_f4113` AS `jst_3210_f4113`,`jst_3210`.`jst_3210_id` AS `jst_3210_id` FROM `jst_3210` UNION ALL SELECT `jst_3207`.`jst_3207_f5171` AS `jst_3207_f5171`,`jst_3207`.`jst_3207_f5170` AS `jst_3207_f5170`,`jst_3207`.`jst_3207_f3993` AS `jst_3207_f3993`,`jst_3207`.`jst_3207_id` AS `jst_3207_id` FROM `jst_3207` UNION ALL SELECT `jst_3129`.`jst_3129_f5382` AS `jst_3129_f5382`,`jst_3129`.`jst_3129_f5381` AS `jst_3129_f5381`,`jst_3129`.`jst_3129_f4078` AS `jst_3129_f4078`,`jst_3129`.`jst_3129_FOREIGNKEY` AS `jst_3129_FOREIGNKEY` FROM `jst_3129` UNION ALL SELECT `jst_3153`.`jst_3153_f5514` AS `jst_3153_f5514`,`jst_3153`.`jst_3153_f5513` AS `jst_3153_f5513`,`jst_3153`.`jst_3153_f4165` AS `jst_3153_f4165`,`jst_3153`.`jst_3153_id` AS `jst_3153_id` FROM `jst_3153` ) AS a, jsf_work w
AND a.project_number=#{workFileProject}
AND w.WORKRECORD_ID=a.project_id AND w.WORKSTATUS=1
